"""Consolidate validated SDK integration and retain rejected ASIO explorations."""
import argparse,hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--campaign',type=Path,required=True);a=p.parse_args();out=a.campaign.resolve()
read=lambda p:json.loads(p.read_text(encoding='utf-8'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
bench=read(out/'numerical/benchmark.json');pcm=read(out/'numerical/pcm.json')
data=dict(date='2026-11-15',dependencies=read(out/'sdk-manifest.json'),provenance=read(out/'realtime/build-manifest.json'),numerical=dict(protocol=bench['protocol'],cases=bench['cases'],pcm=pcm),asioPerformanceAccepted=False,asioPerformanceBlocker='External cl.exe compilations and UnrealEditor activity; up to 12-16 logical cores outside CyDaw. Owned measurement sessions stopped through their control API. No unrelated process or antivirus setting changed.',asioFunctional=read(out/'asio-plugins-smoke.json'),formatFixtures=read(out/'format-fixtures.json'),logs={f.name:dict(sha256=sha(f),text=f.read_text(encoding='utf-8',errors='replace')) for f in out.glob('ctest*.log')},exploratoryAsio={})
for name in ['realtime','realtime-quiet']:
 file=out/name/'results.json'
 if file.exists():
  rows=read(file);data['exploratoryAsio'][name]=dict(accepted=False,processes=len(rows),windows=sum(len(r['cases']) for r in rows),results=[dict(label=r['label'],round=r['round'],audio=r['audio'],shutdown=r['shutdown'],cases={n:{k:v for k,v in c.items() if k!='lastStatus'} for n,c in r['cases'].items()}) for r in rows])
data['harnessHashes']={str(f.relative_to(ROOT)):sha(f) for f in (ROOT/'tests').glob('cyaudio*.py')};data['harnessHashes']['tests/cydsp_complete_provenance.py']=sha(ROOT/'tests/cydsp_complete_provenance.py')
# Explicit path/digest records avoid confusing a source filename containing API
# with a credential key. Digests retain exactly the original provenance values.
def digest_records(value):
 if isinstance(value,dict):
  if value and all(isinstance(v,str) and len(v)==64 and all(c in '0123456789abcdef' for c in v) for v in value.values()):
   return [dict(path=k,sha256=v) for k,v in value.items()]
  return {k:digest_records(v) for k,v in value.items()}
 if isinstance(value,list):return [digest_records(v) for v in value]
 return value
(ROOT/'docs/reports/CyAudioCore032Update.json').write_text(json.dumps(digest_records(data),indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
lines=['# CyAudioCore / CyDSP 0.3.2 : intégration et vérifications','','Campagne locale du 15 novembre 2026, branche `CyDSP-CORE`, base `1e4695d`. Aucun push ni workflow distant. Les dépôts voisins restent en lecture seule.','','## Résultat validé','','Application, worker et tests reconstruits ; **123/123 tests passent**. Les quatre formats de plugins et les cinq fenêtres natives testées fonctionnent. Le corpus DSP de 98 cas est identique bit à bit au précédent moteur Core. **Aucun nouveau comparatif de performances ASIO n’est retenu** : des compilations et une session Unreal extérieures ont perturbé les fenêtres ; les données brutes sont conservées, sans présenter leur différence comme une régression ou un gain du SDK.','','## Versions et changements','', '- CyAudioCore `'+data['dependencies']['CyAudioCore']['revision']+'`.', '- CyDSP `'+data['dependencies']['CyDSP']['revision']+'` (0.3.2).','- CyUI reste au snapshot `7a793e9` pour isoler la mise à jour audio.','- Snapshots Git propres dans `output/cyaudio-032/2026-11-15/sdk`, archives et SHA-256 enregistrés. Reconstruction complète dans `build/cyaudio-032` : aucun mélange d’anciens objets avec les nouveaux headers/layout MatrixConvolver.','- Pins de dépendances et garde CMake actualisés. Aucun algorithme musical ou réglage de qualité remplacé pour améliorer les chiffres.','','CyAudioCore impose désormais un chemin de worker et l’isolation des fournisseurs. CyDaw fournit le chemin absolu du même exécutable avec une nouvelle entrée `--cydsp-worker`. Le pont IPC existant utilise `sameCycle` : soumission d’un ticket, récupération non bloquante dans la boucle événementielle, pas de réenvoi pendant la requête. Les commandes de contrôle et reconfigurations attendent la consommation du ticket. Le callback périphérique parent reste non bloquant. La commodité synchrone est réservée aux probes/tests hors ligne, avec délai borné.','','**Deux processus enfants par plugin restent présents** : pont CyDaw puis worker SDK. Le SDK n’ajoute pas un second bloc fixe de pipeline ; le pipeline extérieur garde son bloc déclaré. Le plafond SDK est de 64 canaux par direction ; cela n’étend pas les huit canaux de l’IPC applicatif. La suppression du pont extérieur et sa migration vers un ordonnanceur dans le parent restent à réaliser ; aucun gain CPU de cette nouvelle architecture n’est affirmé.','','## Contrôle numérique et coûts hors ligne','',f"**{len(pcm['cases'])}/{len(pcm['cases'])} cas bit-identiques**, {pcm['totalSamples']:,} valeurs PCM et zéro allocation C++ observée sur le thread du corpus. Les 52 effets audio et les 16 instruments sont exercés, avec trois configurations par modèle de famille, tailles de blocs variables, expression, retarget et relâchement.",'','Cinq processus neufs par version, ordre alterné, échauffement exclu. Médianes en µs/1024 ; instruments à une voix. Avant = corpus final de la campagne complète Core précédente ; après = même intégration numérique reconstruite avec les SDK actuels. Cette mesure est distincte du pilote et de l’interface. Les cinq valeurs et plages de chaque cas figurent dans le JSON.','','| Cas | Avant | Après | Variation |','| --- | ---: | ---: | ---: |']
keys=['fx:chorus','fx:reverb-pro','fx:halo','fx:pression','fx:empreinte','fx:velours','fx:givre','fx:fournaise','synth:ambre:0','synth:derive:2','synth:bronze:2','synth:jade:0']
for c in bench['cases']:
 if c['name'] in keys:lines.append(f"| {c['name']} | {c['Before']['median']:.2f} | {c['After']['median']:.2f} | {c['deltaPercent']:+.1f} % |")
lines+=['','Ces résultats n’établissent pas un gain général de CyDaw. Les variations proches de zéro ne sont pas significatives à elles seules ; ce microbanc ne fournit pas d’intervalle de confiance. Les surcoûts historiques ReverbPro/Halo et oscillateurs ne sont pas corrigés par cette mise à jour.','','## Vérifications fonctionnelles','','- Build complet Release x64 et graphe de 41 projets de production sans includes ni bibliothèques JUCE.','- Suite native : 123/123 en 502,85 s, incluant Cinéma, Mix, Fonderie, instruments, effets, graphes, fichiers et services.','- Fournisseur sans chemin refusé sans remplacer le fournisseur précédent ; instances réellement isolées.','- JSFX : tempo, automation à offset exact, sauvegarde/restauration et bloc variable de 17 frames, sans bloc de pipeline SDK ajouté.','- Fournisseurs et workers VST3/CLAP/LV2 : chargement, audio, états et fermeture sur fixtures originales conservées. Les fixtures ne prouvent pas la compatibilité de tous les plugins tiers.','- IPC applicatif : audio traité, absence de fuite du signal sec avant la première réponse, automation, état, éditeur et fermeture ; sélection et restauration des presets LV2 également revérifiées.','- Cinq fenêtres VST3 : Prisme, Jade, Kick, ReverbPro et chaîne, dimensions natives, image réellement dessinée et fermeture autonome.','- Huit VST3 simultanés sur Fireface ASIO 48 kHz / 1024, zéro entrée, sorties silencieuses : seize workers observés, transport et signal actifs, latence déclarée d’un bloc extérieur, tous les workers fermés après remise à zéro ; compteurs de blocs manqués nuls sur ce court essai. C’est une vérification fonctionnelle sous charge extérieure, pas un benchmark de performance ou une preuve d’absence d’xruns.','','Les premiers logs de chargement refusé sont conservés : la borne de canaux initialement configurée à 256 a été corrigée à 64 avant les contrôles finaux. L’assertion du test n’a pas été assouplie.','','## Campagnes ASIO perturbées et conservées','','Les mêmes scènes que la campagne précédente ont été lancées avec JUCE, Core précédent et Core actuel : quatre familles d’instruments, mélange audio/MIDI/effets/bus, effets variés, 32 pistes sèches, 16 compresseurs et 16 chaînes Pro. Les contrôles de transport, topologies et signal réussissent pour les scènes achevées. Le dessin UI est supprimé seulement dans les copies QA ; une sonde mesure la racine du rendu. 100 % CPU représente un cœur logique.','','Les compteurs système ont révélé des pointes extérieures de 12 à 16 cœurs logiques. Un inventaire CPU en lecture seule a identifié plusieurs `cl.exe` et `UnrealEditor`, sans les interrompre. Le passage initial a été arrêté via `quit` sur notre seul port de contrôle. Une seconde tentative avec contrôles de calme et reprises a aussi été interrompue quand les compilations ont repris. **Aucune médiane comparative ASIO de cette campagne n’est publiée comme résultat validé.** Les fenêtres terminées, coûts par thread, compteurs système et empreintes restent disponibles pour audit.','','Le script de reprise attend deux intervalles avec charge extérieure ≤ 150 % d’un cœur avant chaque tentative, et rejette une fenêtre dépassant 200 %. Il conserve les tentatives et échoue après trois refus. Ce sont des critères explicites de bruit résiduel, pas une preuve de machine totalement inactive. Le banc plugins/DJ à trois versions est préparé mais n’a pas été exécuté comme campagne de performance.','','## Cibles restantes','', '- **CyDSP / oscillateurs** : `src/engine/SynthParts.h::PhaseWaveforms` appelle encore setFrequency/reset/next pour des phases externes. La 0.3.2 ne fournit pas l’évaluation stateless préparée demandée.','- **CyDSP / historiques** : `include/cydaw/engine/DspHistory.h` et `src/engine/ProEffects.cpp` restent sur l’historique générique, sans taps préparés à capacité puissance de deux. Coût ReverbPro/Halo toujours présent.','- **CyDSP / filtres et FIR courts** : pas d’API publique biquad par sample avec état explicite, flush sélectif ou FIR polyphase conservant les taps/16 frames historiques. Les besoins du [rapport précédent](CyDSPCompleteReuse.fr.md) restent applicables ; aucun retour à l’adaptateur mono d’une frame mesuré huit fois plus lent.','- **CyDaw / IPC** : retirer à terme le pont externe devenu redondant, avec intégration de l’ordonnanceur, UI, états, automation, transport, bus et compensation. Le contrat `sameCycle` ne réalise pas cet ordonnanceur à la place de l’application.','- Les optimisations ADAA, DynamicEqualizer et MatrixConvolver concernent leurs consommateurs SDK. Les topologies musicales spécifiques de CyDaw ne deviennent pas automatiquement ces processeurs. Les FFT et primitives déjà déléguées sont bien reconstruites.','','Ces localisations reposent sur le code et les microbancs ; aucune nouvelle capture de piles CPU n’est annoncée. Pas de nouvelle validation Linux/macOS, écoute humaine ou tous presets/plugins. La composante continue Cinéma et l’échec CUE ASIO historiques restent ouverts, sans assertion masquée.','','## Reproduction et preuves','','MSVC 19.40 x64 Release, `/O2 /Ob2 /MD`, SDK `/fp:strict`, SIMD automatique, sans LTO. Les commandes et options effectives sont enregistrées dans le manifeste, cache CMake et `.tlog`. Les témoins précédents ne doivent pas être reconstruits avec de nouveaux headers.','','```powershell','cmake --preset cyaudio-desktop -B build/cyaudio-032 `','  -DCYDAW_CYAUDIOCORE_SOURCE_DIR=D:/_Project/CyDAW_Project/output/cyaudio-032/2026-11-15/sdk/CyAudioCore `','  -DCYDAW_CYDSP_SOURCE_DIR=D:/_Project/CyDAW_Project/output/cyaudio-032/2026-11-15/sdk/CyDSP `','  -DFETCHCONTENT_SOURCE_DIR_CYUI=D:/_Project/CyDAW_Project/output/cyui-audioviews/2026-11-14/CyUI `','  -DCYUI_IMGUI_DIR=D:/_Project/CyImgui_Interface/third_party/imgui -DCYDAW_ENABLE_ASIO=ON','cmake --build build/cyaudio-032 --config Release --parallel 6','ctest --test-dir build/cyaudio-032 -C Release --output-on-failure','python tests/cydsp_complete_evidence.py --output <nouveau>/numerical --before output/cydsp-complete/2026-11-14/accepted-artifacts/corpus-thread-local.exe --after build/cyaudio-032/Release/cydaw_full_dsp_reuse_tests.exe --rounds 5','python tests/cyaudio_current_pair_build.py --output <nouveau>/realtime --current-build build/cyaudio-032','python tests/cydsp_complete_provenance.py --manifest <nouveau>/realtime/build-manifest.json --previous output/cydsp-complete/2026-11-14/realtime-accepted/build-manifest.json --current-build build/cyaudio-032 --sdk-manifest output/cyaudio-032/2026-11-15/sdk-manifest.json','python tests/cyaudio_sdk_quiet_pair.py --output <nouveau>/realtime --rounds 3 --seconds 5','# Copier le manifeste vers un nouveau dossier plugins avant ce banc :','python tests/cyaudio_sdk_plugin_pair.py --output <nouveau>/plugins --rounds 3 --seconds 5','python tests/cyaudio_sdk_update_report.py --campaign output/cyaudio-032/2026-11-15','```','','Les commandes ASIO supposent la même autorisation matérielle et un pilote Fireface configuré à 1024 frames. Ne pas mesurer pendant une compilation, une autre campagne ou une charge CPU importante.','','[Données, empreintes, répétitions et traces non retenues](reports/CyAudioCore032Update.json). Les PCM, binaires, topologies et logs complets restent dans `output/cyaudio-032/2026-11-15/`.','']
(ROOT/'docs/CyAudioCore032Update.fr.md').write_text('\n'.join(lines),encoding='utf-8')
print('Generated report; ASIO comparative performance explicitly NOT accepted')
